//! US-RR-10-4: the **generated** synthetic ROM covers the edge cases.
//!
//! Story US-RR-10's criterion: generated ROMs exercise overlapping tables,
//! tables ending exactly at ROM end, NaN/Inf/denormal floats and min/max
//! values for every width. This file checks the generated files: the
//! committed `fixtures/public/synthetic/standard.{bin,manifest.toml}`, and
//! the same files freshly generated. It does not check the plan's intent.
//! The checker ([`coverage_problems`]) reads only the ROM bytes and the
//! manifest TOML text, and requires:
//!
//! 1. **Overlap**: at least one pair of tables shares ROM bytes (from the
//!    manifest's `address`/`end`), each table's `overlapped_by` is exactly
//!    the later tables whose bytes it shares, and at least one cell is
//!    clobbered (its final value differs from what the plan wrote).
//! 2. **End of ROM**: the manifest's `rom_size` is the file's length, no
//!    table goes past it, and at least one table's last byte is the ROM's
//!    last byte.
//! 3. **Floats**: for every float storage and byte order the reference codec
//!    accepts, the cells decoded from the ROM include +/-zero, +/-Inf,
//!    +/-subnormal, +/-quiet NaN, +/-signalling NaN (required only if the
//!    codec keeps a signalling NaN bit-exact), and the lowest and largest
//!    finite values.
//! 4. **Integer min/max**: for every integer storage (width x signedness)
//!    and byte order the reference codec accepts, the codec's minimum and
//!    maximum raw values appear in a plain table of exactly that encoding;
//!    for every integer storage the codec accepts a bitfield on, some
//!    bitfield table on it holds the field's 0 and its all-ones value. The
//!    set is derived by probing the codec over `Storage::ALL` x both byte
//!    orders (and the bounds by probing it one past each end), not from a
//!    hand list: a storage the codec learns without generator coverage fails
//!    here.
//! 5. **Independent decode**: decoding every table from the ROM bytes with
//!    the reference codec, using only what the manifest text says about it,
//!    gives the manifest's `raw` value for every cell; the float `class` is
//!    recomputed from the bits; `rom_fnv1a64` is recomputed from the bytes.
//!
//! The sabotage tests at the end remove each edge from the standard plan (or
//! tamper with the generated bytes or text) and check that the checker
//! reports exactly that gap.

use std::collections::BTreeSet;
use std::fs;
use std::path::PathBuf;

use rr_testkit::reference::synthetic::{
    self, MANIFEST_SUFFIX, Plan, ROM_SUFFIX, TablePlan, Values, output_files, standard_plan,
};
use rr_testkit::reference::{
    Bitfield, Encoding, Endian, Layout, Raw, Storage, decode_table, encode,
};

// ---------------------------------------------------------------------------
// The manifest, read back from its text
// ---------------------------------------------------------------------------

/// One `[[table]]` of the manifest, with every cell decoded from the ROM.
struct Table {
    name: String,
    address: usize,
    end: usize,
    encoding: Encoding,
    overlapped_by: Vec<String>,
    cells: Vec<Cell>,
}

/// One manifest cell.
struct Cell {
    /// The manifest's `raw` text.
    raw: String,
    /// The manifest's `planned` text, for a clobbered cell.
    planned: Option<String>,
    /// The value decoded from the ROM bytes by the reference codec.
    decoded: Raw,
}

const ENDIANS: [Endian; 2] = [Endian::Big, Endian::Little];

const fn endian_name(endian: Endian) -> &'static str {
    match endian {
        Endian::Big => "big",
        Endian::Little => "little",
    }
}

fn storage_named(name: &str) -> Option<Storage> {
    Storage::ALL.into_iter().find(|s| s.name() == name)
}

fn usize_of(value: Option<&toml::Value>, what: &str) -> Result<usize, String> {
    value
        .and_then(toml::Value::as_integer)
        .and_then(|v| usize::try_from(v).ok())
        .ok_or_else(|| format!("manifest: {what} is not a non-negative integer"))
}

fn str_of<'a>(value: Option<&'a toml::Value>, what: &str) -> Result<&'a str, String> {
    value
        .and_then(toml::Value::as_str)
        .ok_or_else(|| format!("manifest: {what} is not a string"))
}

fn hex_of(text: &str, what: &str) -> Result<u64, String> {
    text.strip_prefix("0x")
        .and_then(|hex| u64::from_str_radix(hex, 16).ok())
        .ok_or_else(|| format!("manifest: {what} {text:?} is not 0x hex"))
}

/// FNV-1a 64, written out here so the manifest's hash is checked against an
/// implementation that is not the generator's.
fn fnv(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0xcbf2_9ce4_8422_2325, |h, b| {
        (h ^ u64::from(*b)).wrapping_mul(0x100_0000_01b3)
    })
}

/// `raw` as the manifest must write it: a decimal integer, or a fixed-width
/// lowercase `0x` bit pattern for a float.
fn text_of(raw: Raw) -> String {
    match raw {
        Raw::Int(v) => v.to_string(),
        Raw::F32(v) => format!("0x{:08x}", v.to_bits()),
        Raw::F64(v) => format!("0x{:016x}", v.to_bits()),
    }
}

/// IEEE 754 class of a float from its bits: `+zero`, `-inf`, `+qnan`, ...
/// `None` for integers.
fn class_of(raw: Raw) -> Option<String> {
    // (sign, biased exponent, exponent all-ones, fraction, quiet bit)
    let (sign, exponent, ones, fraction, quiet) = match raw {
        Raw::Int(_) => return None,
        Raw::F32(v) => {
            let b = u64::from(v.to_bits());
            (b >> 31, (b >> 23) & 0xFF, 0xFF, b & 0x7F_FFFF, 1 << 22)
        }
        Raw::F64(v) => {
            let b = v.to_bits();
            (
                b >> 63,
                (b >> 52) & 0x7FF,
                0x7FF,
                b & 0xF_FFFF_FFFF_FFFF,
                1 << 51,
            )
        }
    };
    let class = match (exponent, fraction) {
        (0, 0) => "zero",
        (0, _) => "subnormal",
        (e, 0) if e == ones => "inf",
        (e, f) if e == ones && f & quiet != 0 => "qnan",
        (e, _) if e == ones => "snan",
        _ => "normal",
    };
    Some(format!("{}{class}", if sign == 1 { '-' } else { '+' }))
}

/// Parses the manifest text and decodes every table from `rom`, checking
/// each cell against the manifest (criterion 5). Parse errors are fatal;
/// cell mismatches are pushed to `problems`.
fn read_manifest(rom: &[u8], text: &str, problems: &mut Vec<String>) -> Result<Vec<Table>, String> {
    let doc: toml::Table = text
        .parse()
        .map_err(|e| format!("manifest: not TOML: {e}"))?;
    let rom_size = usize_of(doc.get("rom_size"), "rom_size")?;
    if rom_size != rom.len() {
        problems.push(format!(
            "end: manifest rom_size {rom_size} is not the ROM file's length {}",
            rom.len()
        ));
    }
    let hash = hex_of(
        str_of(doc.get("rom_fnv1a64"), "rom_fnv1a64")?,
        "rom_fnv1a64",
    )?;
    if hash != fnv(rom) {
        problems.push(format!(
            "decode: rom_fnv1a64 {hash:#018x} is not the ROM's {:#018x}",
            fnv(rom)
        ));
    }
    let entries = doc
        .get("table")
        .and_then(toml::Value::as_array)
        .ok_or("manifest: no [[table]]")?;
    let mut tables = Vec::with_capacity(entries.len());
    for entry in entries {
        let t = entry
            .as_table()
            .ok_or("manifest: [[table]] is not a table")?;
        let name = str_of(t.get("name"), "table name")?.to_owned();
        let what = |key: &str| format!("{name}.{key}");
        let storage = str_of(t.get("storage"), &what("storage"))?;
        let storage = storage_named(storage).ok_or(format!("{name}: storage {storage:?}"))?;
        let endian = match str_of(t.get("endian"), &what("endian"))? {
            "big" => Endian::Big,
            "little" => Endian::Little,
            other => return Err(format!("{name}: endian {other:?}")),
        };
        let layout = match str_of(t.get("layout"), &what("layout"))? {
            "default" => Layout::Default,
            "bosch-subtract" => Layout::BoschSubtract,
            other => return Err(format!("{name}: layout {other:?}")),
        };
        let mut encoding = Encoding::new(storage, endian).with_layout(layout);
        if let Some(field) = t.get("bitfield") {
            let field = field.as_table().ok_or(format!("{name}: bitfield"))?;
            let mask = hex_of(str_of(field.get("mask"), &what("mask"))?, &what("mask"))?;
            let shift = usize_of(field.get("shift"), &what("shift"))?;
            let shift = u32::try_from(shift).map_err(|_| format!("{name}: shift"))?;
            encoding = encoding.with_bitfield(Bitfield::new(mask, Some(shift)));
        }
        let address = usize_of(t.get("address"), &what("address"))?;
        let end = usize_of(t.get("end"), &what("end"))?;
        let count =
            usize_of(t.get("cols"), &what("cols"))? * usize_of(t.get("rows"), &what("rows"))?;
        let stride = storage.cell_bytes();
        if end != address + count * stride {
            problems.push(format!(
                "decode: {name}: end {end:#x} is not address + cells"
            ));
        }
        let overlapped_by = t
            .get("overlapped_by")
            .and_then(toml::Value::as_array)
            .ok_or(format!("{name}: overlapped_by"))?
            .iter()
            .map(|v| v.as_str().map(str::to_owned))
            .collect::<Option<Vec<_>>>()
            .ok_or(format!("{name}: overlapped_by entry"))?;
        let texts = t
            .get("cells")
            .and_then(toml::Value::as_array)
            .ok_or(format!("{name}: cells"))?;
        if texts.len() != count {
            problems.push(format!("decode: {name}: {} cells for {count}", texts.len()));
        }
        let decoded = decode_table(rom, address, count, &encoding)
            .map_err(|e| format!("decode: {name}: the reference codec refuses: {e}"))?;
        let float_cells = storage.is_float() && encoding.bitfield.is_none();
        let mut cells = Vec::with_capacity(count);
        for (index, (cell, value)) in texts.iter().zip(decoded).enumerate() {
            let c = cell.as_table().ok_or(format!("{name}[{index}]: cell"))?;
            let at = format!("{name}[{index}]");
            let raw = str_of(c.get("raw"), &format!("{at}.raw"))?.to_owned();
            let offset = usize_of(c.get("offset"), &format!("{at}.offset"))?;
            if offset != address + index * stride {
                problems.push(format!("decode: {at}: offset {offset:#x}"));
            }
            if raw != text_of(value) {
                problems.push(format!(
                    "decode: {at}: manifest says {raw}, the ROM decodes to {}",
                    text_of(value)
                ));
            }
            let class = c.get("class").and_then(toml::Value::as_str);
            let want_class = if float_cells { class_of(value) } else { None };
            if class != want_class.as_deref() {
                problems.push(format!(
                    "decode: {at}: class {class:?}, the bits say {want_class:?}"
                ));
            }
            let clobbered = c.get("clobbered").and_then(toml::Value::as_bool) == Some(true);
            let planned = c
                .get("planned")
                .and_then(toml::Value::as_str)
                .map(str::to_owned);
            if clobbered != planned.is_some() || planned.as_deref() == Some(raw.as_str()) {
                problems.push(format!("decode: {at}: bad clobbered/planned"));
            }
            cells.push(Cell {
                raw,
                planned,
                decoded: value,
            });
        }
        tables.push(Table {
            name,
            address,
            end,
            encoding,
            overlapped_by,
            cells,
        });
    }
    Ok(tables)
}

// ---------------------------------------------------------------------------
// What the reference codec supports (probed, not listed)
// ---------------------------------------------------------------------------

fn zero_of(storage: Storage) -> Raw {
    match storage {
        Storage::F32 => Raw::F32(0.0),
        Storage::F64 => Raw::F64(0.0),
        _ => Raw::Int(0),
    }
}

fn stores(raw: Raw, encoding: &Encoding) -> bool {
    encode(raw, encoding, &mut [0_u8; 8], 0).is_ok()
}

/// Every default-layout, non-bitfield encoding the reference codec accepts:
/// `Storage::ALL` x both byte orders, kept when the codec stores a zero.
fn codec_plain_encodings() -> Vec<Encoding> {
    Storage::ALL
        .into_iter()
        .flat_map(|s| ENDIANS.map(|e| Encoding::new(s, e)))
        .filter(|e| stores(zero_of(e.storage), e))
        .collect()
}

/// Every storage the reference codec accepts a bitfield on (`mask = 1`).
fn codec_bitfield_storages() -> Vec<Storage> {
    Storage::ALL
        .into_iter()
        .filter(|s| {
            let encoding = Encoding::new(*s, Endian::Big).with_bitfield(Bitfield::new(1, None));
            stores(Raw::Int(0), &encoding)
        })
        .collect()
}

/// The codec's inclusive integer range for `encoding`: the storage's (or
/// bitfield's) stated bounds, confirmed by the codec storing each bound and
/// refusing one past it.
fn codec_int_range(encoding: &Encoding, problems: &mut Vec<String>) -> (i128, i128) {
    let (min, max) = match encoding.bitfield {
        Some(Bitfield { mask, shift }) => (0, i128::from(mask >> shift)),
        None => encoding.storage.int_range(),
    };
    let ok = |v: i128| stores(Raw::Int(v), encoding);
    if !(ok(min) && ok(max) && !ok(min - 1) && !ok(max + 1)) {
        problems.push(format!(
            "codec: {encoding:?}: {min}..={max} is not the range the codec stores"
        ));
    }
    (min, max)
}

/// Whether the codec keeps a signalling NaN bit-exact for `encoding`.
fn codec_keeps_snan(encoding: &Encoding) -> bool {
    let snan = match encoding.storage {
        Storage::F32 => Raw::F32(f32::from_bits(0x7F80_0001)),
        _ => Raw::F64(f64::from_bits(0x7FF0_0000_0000_0001)),
    };
    let mut bytes = [0_u8; 8];
    encode(snan, encoding, &mut bytes, 0).is_ok()
        && decode_table(&bytes, 0, 1, encoding)
            .is_ok_and(|v| v.first().map(|v| text_of(*v)) == Some(text_of(snan)))
}

// ---------------------------------------------------------------------------
// The checker
// ---------------------------------------------------------------------------

/// Every way `rom` + `manifest` (the generated files) fall short of the
/// criterion; empty when every edge is covered.
fn coverage_problems(rom: &[u8], manifest: &str) -> Vec<String> {
    let mut problems = Vec::new();
    let tables = match read_manifest(rom, manifest, &mut problems) {
        Ok(tables) => tables,
        Err(error) => {
            problems.push(error);
            return problems;
        }
    };

    // 1. Overlapping tables, from the byte ranges.
    let mut pairs = 0;
    for (i, a) in tables.iter().enumerate() {
        let later: Vec<String> = tables
            .iter()
            .skip(i + 1)
            .filter(|b| b.address < a.end && a.address < b.end)
            .map(|b| b.name.clone())
            .collect();
        pairs += later.len();
        if later != a.overlapped_by {
            problems.push(format!(
                "overlap: {}: overlapped_by {:?}, but the byte ranges say {later:?}",
                a.name, a.overlapped_by
            ));
        }
    }
    if pairs == 0 {
        problems.push("overlap: no two tables overlap in bytes".to_owned());
    }
    let clobbered = tables
        .iter()
        .flat_map(|t| &t.cells)
        .filter(|c| c.planned.as_ref().is_some_and(|p| *p != c.raw))
        .count();
    if clobbered == 0 {
        problems.push("overlap: no cell is clobbered by a later table".to_owned());
    }

    // 2. A table ending exactly at the end of the ROM.
    if let Some(t) = tables.iter().find(|t| t.end > rom.len()) {
        problems.push(format!("end: {} ends past the ROM", t.name));
    }
    if !tables.iter().any(|t| t.end == rom.len()) {
        problems.push("end: no table's last byte is the ROM's last byte".to_owned());
    }

    // Decoded values of the plain (default layout, no bitfield) tables of
    // exactly `encoding`.
    let plain = |encoding: &Encoding| -> BTreeSet<String> {
        tables
            .iter()
            .filter(|t| t.encoding == *encoding)
            .flat_map(|t| t.cells.iter().map(|c| text_of(c.decoded)))
            .collect()
    };

    for encoding in codec_plain_encodings() {
        let label = format!("{} {}", encoding.storage, endian_name(encoding.endian));
        let values = plain(&encoding);
        if encoding.storage.is_float() {
            // 3. Float specials and finite extremes.
            let classes: BTreeSet<String> = tables
                .iter()
                .filter(|t| t.encoding == encoding)
                .flat_map(|t| &t.cells)
                .filter_map(|c| class_of(c.decoded))
                .collect();
            let mut want = vec![
                "+zero",
                "-zero",
                "+inf",
                "-inf",
                "+subnormal",
                "-subnormal",
                "+qnan",
                "-qnan",
            ];
            if codec_keeps_snan(&encoding) {
                want.extend(["+snan", "-snan"]);
            }
            for class in want {
                if !classes.contains(class) {
                    problems.push(format!("float: {label}: no {class} cell"));
                }
            }
            let (min, max) = match encoding.storage {
                Storage::F32 => (Raw::F32(f32::MIN), Raw::F32(f32::MAX)),
                _ => (Raw::F64(f64::MIN), Raw::F64(f64::MAX)),
            };
            for (what, value) in [("min", min), ("max", max)] {
                if !values.contains(&text_of(value)) {
                    problems.push(format!("float: {label}: no {what} {}", text_of(value)));
                }
            }
        } else {
            // 4. Integer min/max for this width, signedness and byte order.
            let (min, max) = codec_int_range(&encoding, &mut problems);
            for (what, value) in [("min", min), ("max", max)] {
                if !values.contains(&value.to_string()) {
                    problems.push(format!("int: {label}: no {what} {value}"));
                }
            }
        }
    }

    // 4. Bitfield 0 and all-ones, for every storage that takes a bitfield.
    for storage in codec_bitfield_storages() {
        let covered = tables.iter().any(|t| {
            t.encoding.storage == storage
                && t.encoding.layout == Layout::Default
                && t.encoding.bitfield.is_some()
                && {
                    let (min, max) = codec_int_range(&t.encoding, &mut Vec::new());
                    let values: BTreeSet<String> =
                        t.cells.iter().map(|c| text_of(c.decoded)).collect();
                    values.contains(&min.to_string()) && values.contains(&max.to_string())
                }
        });
        if !covered {
            problems.push(format!(
                "bitfield: no bitfield on {storage} holds both its 0 and all-ones values"
            ));
        }
    }
    problems
}

// ---------------------------------------------------------------------------
// The generated files
// ---------------------------------------------------------------------------

fn committed_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("fixtures")
        .join("public")
        .join("synthetic")
}

/// The standard plan's ROM and manifest text, as generated now.
fn fresh(plan: &Plan) -> Result<(Vec<u8>, String), String> {
    let files = output_files(plan).map_err(|e| e.to_string())?;
    let file = |suffix: &str| {
        files
            .iter()
            .find(|(name, _)| *name == format!("{}{suffix}", plan.name))
            .map(|(_, bytes)| bytes.clone())
            .ok_or(format!("no {suffix} file"))
    };
    let manifest = String::from_utf8(file(MANIFEST_SUFFIX)?).map_err(|e| e.to_string())?;
    Ok((file(ROM_SUFFIX)?, manifest))
}

#[test]
fn the_committed_standard_rom_covers_every_edge() {
    let name = standard_plan().name;
    let dir = committed_dir();
    let rom = fs::read(dir.join(format!("{name}{ROM_SUFFIX}"))).expect("committed ROM");
    let manifest = fs::read_to_string(dir.join(format!("{name}{MANIFEST_SUFFIX}")))
        .expect("committed manifest");
    let problems = coverage_problems(&rom, &manifest);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

#[test]
fn the_freshly_generated_standard_rom_covers_every_edge() {
    let (rom, manifest) = fresh(&standard_plan()).expect("the standard plan generates");
    let problems = coverage_problems(&rom, &manifest);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

#[test]
fn the_probed_codec_sets_are_what_the_generator_must_cover() {
    // The probe finds every storage in both byte orders except
    // little-endian u20 (an SH-2A instruction field), and bitfields on every
    // integer storage. Listed here only to show the probe works; the
    // checker uses the probe, so a storage the codec gains is covered or
    // fails.
    let plain: Vec<String> = codec_plain_encodings()
        .iter()
        .map(|e| format!("{}-{}", e.storage, endian_name(e.endian)))
        .collect();
    assert_eq!(plain.len(), 2 * Storage::ALL.len() - 1, "{plain:?}");
    assert!(!plain.contains(&"u20-little".to_owned()));
    let bitfields = codec_bitfield_storages();
    assert_eq!(bitfields.len(), Storage::ALL.len() - 2, "{bitfields:?}");
    assert!(bitfields.iter().all(|s| !s.is_float()));
    // The f32/f64 signalling NaNs are kept bit-exact, so they are required.
    for storage in [Storage::F32, Storage::F64] {
        for endian in ENDIANS {
            assert!(codec_keeps_snan(&Encoding::new(storage, endian)));
        }
    }
}

// ---------------------------------------------------------------------------
// Sabotage: each removed edge is reported
// ---------------------------------------------------------------------------

/// Problems of the standard plan after `edit`.
#[expect(
    clippy::expect_used,
    reason = "test-only helper outside a #[test] fn; panicking is how it fails the calling test"
)]
fn problems_after(edit: impl FnOnce(&mut Vec<TablePlan>)) -> Vec<String> {
    let mut plan = standard_plan();
    edit(&mut plan.tables);
    let (rom, manifest) = fresh(&plan).expect("the edited plan still generates");
    coverage_problems(&rom, &manifest)
}

fn drop_tables(tables: &mut Vec<TablePlan>, names: &[&str]) {
    let before = tables.len();
    tables.retain(|t| !names.contains(&t.name.as_str()));
    assert_eq!(
        tables.len(),
        before - names.len(),
        "unknown name in {names:?}"
    );
}

/// Rewrites the named table so every value `drop` selects becomes the
/// table's first value that it does not select. The table keeps its size
/// and address, so nothing else in the ROM moves.
#[expect(
    clippy::expect_used,
    reason = "test-only helper outside a #[test] fn; panicking is how it fails the calling test"
)]
fn without_values(tables: &mut [TablePlan], name: &str, drop: impl Fn(Raw) -> bool) {
    let table = tables
        .iter_mut()
        .find(|t| t.name == name)
        .expect("table in the standard plan");
    let cells = table.dims.cells().expect("cells");
    let values: Vec<Raw> = match table.values {
        Values::Specials => synthetic::specials(&table.encoding),
        Values::Extremes => synthetic::extremes(&table.encoding),
        Values::Explicit(ref v) => v.clone(),
    };
    let filler = *values.iter().find(|v| !drop(**v)).expect("a value to keep");
    assert!(values.iter().any(|v| drop(*v)), "{name}: nothing to drop");
    let edited = values
        .into_iter()
        .cycle()
        .take(cells)
        .map(|v| if drop(v) { filler } else { v })
        .collect();
    table.values = Values::Explicit(edited);
}

#[track_caller]
fn assert_reports(problems: &[String], want: &[&str]) {
    for w in want {
        assert!(
            problems.iter().any(|p| p == w),
            "expected {w:?} among the problems:\n{}",
            problems.join("\n")
        );
    }
}

#[test]
fn removing_every_overlap_is_reported() {
    let problems = problems_after(|tables| {
        // Keep each table only if it shares no byte with an earlier kept one.
        let mut kept: Vec<TablePlan> = Vec::new();
        for t in tables.drain(..) {
            let len = t.dims.cells().unwrap_or(0) * t.encoding.storage.cell_bytes();
            let clash = kept.iter().any(|k| {
                let klen = k.dims.cells().unwrap_or(0) * k.encoding.storage.cell_bytes();
                k.address < t.address + len && t.address < k.address + klen
            });
            if !clash {
                kept.push(t);
            }
        }
        *tables = kept;
    });
    assert_reports(
        &problems,
        &[
            "overlap: no two tables overlap in bytes",
            "overlap: no cell is clobbered by a later table",
        ],
    );
}

#[test]
fn removing_the_end_of_rom_table_is_reported() {
    let problems = problems_after(|t| drop_tables(t, &["end-of-rom-f64-be-specials"]));
    assert_eq!(
        problems,
        ["end: no table's last byte is the ROM's last byte"]
    );
}

#[test]
fn removing_a_float_special_is_reported() {
    let is_neg_inf = |v: Raw| matches!(v, Raw::F32(f) if f.to_bits() == 0xFF80_0000);
    let problems = problems_after(|t| without_values(t, "f32-le-specials", is_neg_inf));
    assert_eq!(problems, ["float: f32 little: no -inf cell"]);

    // f64 big-endian specials appear twice (the end-of-ROM table too).
    let is_snan = |v: Raw| class_of(v).is_some_and(|c| c.ends_with("snan"));
    let is_subnormal = |v: Raw| class_of(v).as_deref() == Some("-subnormal");
    let problems = problems_after(|t| {
        for name in ["f64-be-specials", "end-of-rom-f64-be-specials"] {
            without_values(t, name, is_snan);
        }
        without_values(t, "f64-le-specials", is_subnormal);
    });
    assert_eq!(
        problems,
        [
            "float: f64 big: no +snan cell",
            "float: f64 big: no -snan cell",
            "float: f64 little: no -subnormal cell",
        ]
    );
}

#[test]
fn removing_an_integer_min_or_max_is_reported() {
    let problems = problems_after(|t| {
        drop_tables(
            t,
            &["u24-le-extremes", "u24-le-specials", "i64-be-specials"],
        );
        let max = Storage::I64.int_range().1;
        without_values(t, "i64-be-extremes", |v| v == Raw::Int(max));
    });
    assert_eq!(
        problems,
        [
            "int: u24 little: no min 0",
            "int: u24 little: no max 16777215",
            "int: i64 big: no max 9223372036854775807",
        ]
    );
}

#[test]
fn removing_a_bitfield_extreme_is_reported() {
    let problems = problems_after(|t| {
        drop_tables(t, &["bitfield-i24-be-mask-all"]);
        without_values(t, "bitfield-u32-be-mask-0x80000001", |v| v == Raw::Int(0));
    });
    assert_eq!(
        problems,
        [
            "bitfield: no bitfield on u32 holds both its 0 and all-ones values",
            "bitfield: no bitfield on i24 holds both its 0 and all-ones values",
        ]
    );
}

#[test]
fn tampered_rom_bytes_or_manifest_values_are_reported() {
    let (rom, manifest) = fresh(&standard_plan()).expect("generates");
    assert!(coverage_problems(&rom, &manifest).is_empty());

    // Flip the u16 big-endian max (FF FF at cell 1) to FF FE.
    let doc: toml::Table = manifest.parse().expect("TOML");
    let table = doc["table"]
        .as_array()
        .expect("tables")
        .iter()
        .find(|t| t["name"].as_str() == Some("u16-be-extremes"))
        .expect("u16-be-extremes");
    let at = usize::try_from(table["address"].as_integer().expect("address")).expect("usize") + 3;
    let mut bad_rom = rom.clone();
    bad_rom[at] ^= 1;
    let problems = coverage_problems(&bad_rom, &manifest);
    assert_reports(
        &problems,
        &["decode: u16-be-extremes[1]: manifest says 65535, the ROM decodes to 65534"],
    );
    assert!(
        problems
            .iter()
            .any(|p| p.starts_with("decode: rom_fnv1a64"))
    );

    // A manifest value that the bytes do not hold.
    let bad_manifest = manifest.replacen("raw = \"0x7fc00000\"", "raw = \"0x7fc00002\"", 1);
    assert_ne!(bad_manifest, manifest);
    let problems = coverage_problems(&rom, &bad_manifest);
    assert_eq!(problems.len(), 1, "{problems:?}");
    assert!(
        problems[0].ends_with("manifest says 0x7fc00002, the ROM decodes to 0x7fc00000"),
        "{problems:?}"
    );
}
